export function parseObservationJsonLines(
  text,
  label = "observations",
  { laneRunId = null } = {},
) {
  const events = [];
  for (const [index, line] of text.split(/\r?\n/u).entries()) {
    if (line.trim() === "") continue;
    let event;
    try {
      event = JSON.parse(line);
    } catch (error) {
      throw new SyntaxError(`${label}:${index + 1}: ${error.message}`);
    }
    const normalized = normalizeObservationEvent(event, `${label}:${index + 1}`);
    if (laneRunId !== null) {
      normalized.laneRunId = canonicalObservationLaneRunId(
        normalized.laneRunId,
        laneRunId,
      );
    }
    events.push(normalized);
  }
  const identities = new Set();
  for (const event of events) {
    const identity = `${event.laneRunId}\0${event.sequence}`;
    if (identities.has(identity)) {
      throw new Error(`${label}: duplicate observation sequence ${event.sequence}`);
    }
    identities.add(identity);
  }
  return events.sort((left, right) => (
    Date.parse(left.at) - Date.parse(right.at) || left.sequence - right.sequence
  ));
}

function zeroMap(keys) {
  return Object.fromEntries(keys.map((key) => [key, 0]));
}

function blockClaim(events, milestone, block, owner = null) {
  const claims = events.filter((event) => (
    event.type === "block-claim"
    && event.milestone === milestone
    && event.block === block
    && event.owner === owner
  ));
  if (claims.length > 1) {
    throw new Error(`${milestone}.${block} has duplicate claim events`);
  }
  return claims[0] ?? null;

