  "block-claim": [...BASE_FIELDS, "block", "owner", "claimed", "reason"],
  "semantic-action": [
    ...BASE_FIELDS,
    "actionId",
    "actionClass",
    "disposition",
    "episodeId",
    "retriedClass",
    "binaryExcavation",
  ],
