  "assertion-wait": [
    ...BASE_FIELDS,
    "owner",
    "assertion",
    "attempt",
    "durationMs",
    "pass",
  ],
  "host-load-sample": [
    ...BASE_FIELDS,
    "loadavg1",
    "loadavg5",
    "loadavg15",
    "ceiling1",
    "ceiling5",
    "ceiling15",
  ],
  "api-request": [
    ...BASE_FIELDS,
    "provider",
    "operation",
    "requestId",
    "outcome",
    "retryOf",
  ],
});

