        ...base,
        episodeId: requiredString(event.episodeId, `${label}.episodeId`),
        carrier: requiredEnum(event.carrier, CARRIERS, `${label}.carrier`),
        attribution,
        subAttribution,
        outcome,
        recoveredAt,
        actionCount: requiredInteger(
          event.actionCount,
          `${label}.actionCount`,
          COSTLY_EPISODE_THRESHOLD_ACTIONS,
