import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const readyPath = resolve(root, '.snapback/dev.ready.json.application-ready');
const outputPath = resolve(root, 'snapback/dev.binding.json');
const receipt = JSON.parse(await readFile(readyPath, 'utf8'));
const binding = receipt.binding;

if (binding?.format !== 'snapback.app-binding.v1') {
  throw new Error(`Application-ready receipt has no admitted binding: ${readyPath}`);
}
if (binding.target?.origin !== 'http://127.0.0.1:42020') {
  throw new Error(`Refusing unexpected backend origin ${binding.target?.origin}`);
}
await writeFile(outputPath, `${JSON.stringify(binding, null, 2)}\n`, 'utf8');
process.stdout.write(`${JSON.stringify({ ok: true, outputPath, descriptorIdentity: binding.descriptorIdentity })}\n`);

