import { useMemo, useState } from 'react';
import { Link, Stack, useRouter } from 'expo-router';
import { Platform, SafeAreaView, StyleSheet, Text, View } from 'react-native';
import {
  SnapbackProvider,
  useAuth,
  useCurrentPrincipal,
  useMutation,
} from '@expo/snapback-react/familiar';

import { app, api } from '../snapback/generated/api.mjs';
import binding from '../snapback/dev.binding.json';
import { AuthForm, palette, spacing, typeScale } from '../ui';

function errorMessage(error: unknown): string {
  if (error instanceof Error && error.message) return error.message;
  return 'Something went wrong. Please try again.';
}

function AuthBoundary({ children }: Readonly<{ children: React.ReactNode }>) {
  const auth = useAuth();
  const principal = useCurrentPrincipal();
  const upsertProfile = useMutation(api.profiles.upsert);
  const router = useRouter();
  const [mode, setMode] = useState<'sign-up' | 'sign-in'>('sign-in');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [recoveryCodes, setRecoveryCodes] = useState<readonly string[] | null>(null);

  if (principal.status === 'loading' || principal.status === 'refreshing') {
    return <View style={styles.center}><Text style={styles.muted}>Opening Clique…</Text></View>;
  }
  if (principal.status === 'blocked') {
    return <View style={styles.center}><Text style={styles.error}>Authentication is unavailable.</Text></View>;
  }

  if (principal.status === 'anonymous') {
    const submit = async () => {
      setSubmitting(true);
      setError('');
      setRecoveryCodes(null);
      try {
        if (mode === 'sign-up') {
          const result = await auth.signUpWithPassword({ email: email.trim(), password });
          setRecoveryCodes(result.recoveryCodes);
          const local = email.trim().split('@')[0].toLowerCase().replace(/[^a-z0-9_]/g, '_');
          const handle = (local.length >= 3 ? local : `${local}___`).slice(0, 20);
          await upsertProfile({
            displayName: local || 'New member',
            handle,
            bio: '',
            location: '',
            link: '',
          });
        } else {
          await auth.signInWithPassword({ email: email.trim(), password });
        }
        router.replace('/');
      } catch (caught) {
        setError(errorMessage(caught));
      } finally {
        setSubmitting(false);
      }
    };
    return (
      <SafeAreaView style={styles.authPage}>
        <View style={styles.authCard}>
          <AuthForm
            email={email}
            errorText={error}
            mode={mode}
            onChangeEmail={setEmail}
            onChangePassword={setPassword}
            onSubmit={() => void submit()}
            onToggleMode={() => {
              setError('');
              setMode((value) => value === 'sign-in' ? 'sign-up' : 'sign-in');
            }}
            password={password}
            submitting={submitting}
          />
          {recoveryCodes ? (
            <View style={styles.recovery}>
              <Text style={styles.recoveryTitle}>Save these recovery codes now.</Text>
              <Text selectable style={styles.recoveryCodes}>{recoveryCodes.join('\n')}</Text>
            </View>
          ) : null}
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.shell}>
      <View style={styles.nav}>
        <Link href="/" style={styles.brand}>Clique</Link>
        <View style={styles.navLinks}>
          <Link href="/" style={styles.navLink}>Feed</Link>
          <Link href="/profile/edit" style={styles.navLink}>Profile</Link>
          <Link href="/settings" style={styles.navLink}>Settings</Link>
        </View>
      </View>
      <View style={styles.content}>{children}</View>
    </SafeAreaView>
  );
}

export default function RootLayout() {
  const platform = useMemo(() => Platform.OS === 'web' ? 'expo-web' as const : 'memory' as const, []);
  return (
    <SnapbackProvider
      app={app}
      binding={binding as never}
      fallback={<View style={styles.center}><Text style={styles.muted}>Connecting to Clique…</Text></View>}
      platform={platform}
      storagePartition="clique-primary"
    >
      <AuthBoundary>
        <Stack screenOptions={{ headerShown: false }} />
      </AuthBoundary>
    </SnapbackProvider>
  );
}

