            .then(() => router.replace(`/profile/${values.handle}`))
            .catch((caught: unknown) => setError(caught instanceof Error ? caught.message : 'Could not save profile.'))
            .finally(() => setSaving(false));
        }}
        saving={saving}
        values={values}
      />
    </ScrollView>
  );
}

