      await writer.assertionWait('M1', { owner: 'suite', assertion, attempt: 1, durationMs, pass: true });
      tests.push({ assertion, name, pass: true, durationMs });
    } catch (error) {
      const durationMs = Math.max(0, performance.now() - began);
      await writer.assertionWait('M1', { owner: 'suite', assertion, attempt: 1, durationMs, pass: false });
      tests.push({ assertion, name, pass: false, durationMs, error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  }

  await writer.claim('M1', 'browserAssertionWait', { owner: 'suite' });
  const suffix = `${process.pid}${Date.now()}`.slice(-10);
  const email = `m1-${suffix}@example.com`;
  const password = 'CliqueM1!secure';
  const handle = `m1_${suffix}`.slice(0, 20);
  const primary = await createClient('m1-primary');
  extraClients.push(primary);

  await test('m1-a01', 'password signup succeeds', async () => {
    const signup = await primary.auth.signUpWithPassword({ email, password });
    assert.equal(signup.recoveryCodes.length, 8);
  });
  await test('m1-a02', 'signup settles authenticated principal', async () => {
    assert.equal(primary.auth.currentPrincipal().status, 'authenticated');
  });
  await mutate(primary, api.profiles.upsert, {
    displayName: 'Milestone One', handle, bio: 'Initial bio', location: 'Oakland, CA', link: 'https://example.com/m1',
  }, `m1-profile-${suffix}`);

  await test('m1-a03', 'duplicate handle is refused and wired to visible profile error', async () => {
    const duplicate = await createClient('m1-duplicate-handle');
    extraClients.push(duplicate);
    await duplicate.auth.signUpWithPassword({ email: `other-${suffix}@example.com`, password });
    await assert.rejects(mutate(duplicate, api.profiles.upsert, {
      displayName: 'Other Person', handle, bio: '', location: '', link: '',
    }, `m1-duplicate-handle-${suffix}`));
    const routeSource = await readFile(resolve(root, 'app/profile/edit.tsx'), 'utf8');
    const kitSource = await readFile(resolve(root, 'ui/src/ProfileForm.tsx'), 'utf8');
    assert(routeSource.includes('setError('));
    assert(kitSource.includes('testID="sm-profile-error"'));
  });

  await test('m1-a04', 'duplicate email is refused and auth error is visible', async () => {
    const duplicate = await createClient('m1-duplicate-email');
    extraClients.push(duplicate);
    await assert.rejects(duplicate.auth.signUpWithPassword({ email, password }));
    const routeSource = await readFile(resolve(root, 'app/_layout.tsx'), 'utf8');
    const kitSource = await readFile(resolve(root, 'ui/src/AuthForm.tsx'), 'utf8');
    assert(routeSource.includes('errorText={error}'));
    assert(kitSource.includes('testID="sm-auth-error"'));
  });

  await test('m1-a08', 'display name and bio edit persist', async () => {
    await mutate(primary, api.profiles.upsert, {
      displayName: 'Milestone One Edited', handle, bio: 'Edited bio is persistent.', location: 'Oakland, CA', link: 'https://example.com/m1',
    }, `m1-edit-${suffix}`);
    const matches = await rows(primary, api.profiles.byHandle, { handle });
    assert.equal(matches[0].displayName, 'Milestone One Edited');
    assert.equal(matches[0].bio, 'Edited bio is persistent.');
  });

  await test('m1-a10', 'fixture avatar replacement settles through profile mutation', async () => {
    await mutate(primary, api.profiles.upsert, {
      displayName: 'Milestone One Edited', handle, avatarUri: 'assets/fixtures/avatar-alice.png', bio: 'Edited bio is persistent.', location: 'Oakland, CA', link: 'https://example.com/m1',
    }, `m1-avatar-${suffix}`);
  });
  await test('m1-a11', 'saved fixture avatar projects on profile', async () => {
    const matches = await rows(primary, api.profiles.byHandle, { handle });
    assert.equal(matches[0].avatarUri, 'assets/fixtures/avatar-alice.png');
    const kitSource = await readFile(resolve(root, 'ui/src/ProfileForm.tsx'), 'utf8');
    assert(kitSource.includes('avatarUri'));
  });

  const failed = tests.filter((entry) => !entry.pass);
  const receipt = {
    schemaVersion: 'clique-suite-receipt.v1',
    milestone: 'm1',
    pass: failed.length === 0,
    startedAt,
    endedAt: new Date().toISOString(),
    coveredAssertions,
    tests,
    replay: { actions: replay.actions, receipt: replay.receipt },
    generatedProfile: app.authoringProfile,
  };
  await Promise.all([...replay.clients, ...extraClients].map((client) => client.dispose()));
  return receipt;
}

async function main() {
  const milestone = selectedMilestone(process.argv.slice(2));
  const upper = milestone.toUpperCase();
  const observationPath = resolve(root, `receipts/${milestone}-suite.observations.jsonl`);
  const writer = new ObservationWriter({ path: observationPath, laneRunId });
  await writer.initialize();

  let receipt;
  if (milestone === 'm1') receipt = await runM1(writer);
  else throw new Error(`${upper} acceptance is dependency-blocked until its implementation milestone starts.`);

  const receiptPath = resolve(root, `receipts/${milestone}-suite.json`);
  await writeFile(receiptPath, `${JSON.stringify(receipt, null, 2)}\n`, 'utf8');
  let status = {};
  try { status = JSON.parse(await readFile(resolve(root, 'suite-status.json'), 'utf8')); } catch {}
  status[milestone] = { pass: receipt.pass, receipt: `receipts/${milestone}-suite.json` };
  await writeFile(resolve(root, 'suite-status.json'), `${JSON.stringify(status, null, 2)}\n`, 'utf8');
  process.stdout.write(`${JSON.stringify({ milestone, pass: receipt.pass, receipt: `receipts/${milestone}-suite.json`, observations: `receipts/${milestone}-suite.observations.jsonl` })}\n`);
  if (!receipt.pass) process.exitCode = 1;
}

await main();

