{
  "name": "clique",
  "private": true,
  "type": "module",
  "main": "expo-router/entry",
  "packageManager": "bun@1.3.12",
  "scripts": {
    "generate": "snapback generate snapback",
    "backend": "snapback dev snapback --port 42020 --external-client-origin http://127.0.0.1:42021",
    "start": "expo start --web --port 42021",
    "web": "expo start --web --port 42021",
    "binding": "node scripts/write-dev-binding.mjs",
    "typecheck": "tsc --noEmit",
    "export:ios": "expo export --platform ios",
    "acceptance": "node scripts/acceptance.mjs"
  },
  "dependencies": {
    "@expo/metro-runtime": "~57.0.8",
    "@expo/snapback-acceptance": "0.1.25",
    "@expo/snapback-cli": "0.1.25",
    "@expo/snapback-client": "0.1.25",
    "@expo/snapback-codegen": "0.1.25",
    "@expo/snapback-expo": "0.1.25",
    "@expo/snapback-react": "0.1.25",
    "expo": "~57.0.7",
    "expo-crypto": "~57.0.1",
    "expo-file-system": "~57.0.1",
    "expo-image-picker": "~57.0.7",
    "expo-router": "~57.0.16",
    "expo-secure-store": "~57.0.1",
    "react": "19.2.3",
    "react-dom": "19.2.3",
    "react-native": "0.86.2",
    "react-native-web": "^0.21.2"
  },
  "devDependencies": {
    "@types/react": "~19.2.0",
    "ajv": "8.20.0",
    "fake-indexeddb": "^6.2.5",
    "playwright": "1.62.1",
    "typescript": "~6.0.3"
  }
}
import { defineAuth } from '@expo/snapback-codegen/define';
import { defineSchema, defineTable, v } from './generated/server';

const authProgram = defineAuth({
  version: 1,
  custody: 'durable-required',
  mechanisms: {
    password: {
      kind: 'password',
      identifier: 'email',
      provider: 'builtIn',
      recovery: 'recoveryCodes',
      minimumLength: 8,
    },
  },
  assuranceRequirements: {},
  recoveryPolicy: {
    recoveryCodes: {
      enabled: true,
      requiredWhen: 'no-independent-recovery',
      rotateAfterUse: true,
      plaintextCustody: 'one-time-response',
    },
    lastAuthenticator: 'enforce',
  },
  guestPolicy: { enabled: false },
  secretReferences: {},
});

export default defineSchema(
  {
    profiles: defineTable({
      userId: v.string(),
      displayName: v.string(),
      handle: v.string(),
      avatarUri: v.optional(v.string()),
      bio: v.string(),
      location: v.string(),
      link: v.string(),
    })
      .visibility({ kind: 'public-read' })
      .index('by_user', ['userId'], { unique: true })
      .index('by_handle', ['handle'], { unique: true })
      .sync(),
  },
  { auth: { mode: 'sessions' }, authProgram },
);
import { mutation, query, v } from './generated/server';

export const mine = query({
  args: {},
  returns: v.array(v.doc('profiles')),
  auth: 'authenticated',
  reads: ['profiles'],
  handler: async (ctx) => ctx.db
    .query('profiles')
    .withIndex('by_user', (q) => q.eq('userId', ctx.auth.userId))
    .take(1)
    .collect(),
});

export const byHandle = query({
  args: { handle: v.string() },
  returns: v.array(v.doc('profiles')),
  auth: 'authenticated',
  reads: ['profiles'],
  handler: async (ctx, args) => ctx.db
    .query('profiles')
    .withIndex('by_handle', (q) => q.eq('handle', args.handle))
    .take(1)
    .collect(),
});

export const all = query({
  args: {},
  returns: v.array(v.doc('profiles')),
  auth: 'authenticated',
  reads: ['profiles'],
  handler: async (ctx) => ctx.db.query('profiles').take(100).collect(),
});

export const upsert = mutation({
  args: {
    displayName: v.string(),
    handle: v.string(),
    avatarUri: v.optional(v.string()),
    bio: v.string(),
    location: v.string(),
    link: v.string(),
  },
  returns: v.object({ profileId: v.id('profiles') }),
  auth: 'authenticated',
  reads: ['profiles'],
  writes: ['profiles'],
  handler: async (ctx, args) => {
    if (args.displayName.length < 1 || args.displayName.length > 50) {
      throw new Error('Display name must be 1–50 characters.');
    }
    if (!/^[a-z0-9_]{3,20}$/.test(args.handle)) {
      throw new Error('Handle must be 3–20 lowercase letters, numbers, or underscores.');
    }
    if (args.bio.length > 200) throw new Error('Bio must be at most 200 characters.');
    if (args.location.length > 50) throw new Error('Location must be at most 50 characters.');
    if (args.link !== '' && !/^https?:\/\/[^\s]+$/.test(args.link)) {
      throw new Error('Link must be an http(s) URL.');
    }

    const mine = await ctx.db
      .query('profiles')
      .withIndex('by_user', (q) => q.eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    const handleRows = await ctx.db
      .query('profiles')
      .withIndex('by_handle', (q) => q.eq('handle', args.handle))
      .take(1)
      .collect();
    const existing = mine[0];
    const handleOwner = handleRows[0];
    if (handleOwner && (!existing || handleOwner._id !== existing._id)) {
      throw new Error('Handle is already taken.');
    }
    const values = {
      displayName: args.displayName,
      handle: args.handle,
      bio: args.bio,
      location: args.location,
      link: args.link,
      ...(args.avatarUri ? { avatarUri: args.avatarUri } : {}),
    };
    if (existing) {
      await ctx.db.patch('profiles', existing._id, values);
      return { profileId: existing._id };
    }
    const profileId = await ctx.db.insert('profiles', {
      userId: ctx.auth.userId,
      ...values,
    });
    return { profileId };
  },
});
import { useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { FeedTabs, palette, spacing, typeScale } from '../ui';

export default function FeedScreen() {
  const [tab, setTab] = useState<'following' | 'global' | 'trending'>('following');
  return (
    <View style={styles.page}>
      <FeedTabs active={tab} onChange={setTab} />
      <View style={styles.empty}>
        <Text style={styles.title}>Welcome to Clique</Text>
        <Text style={styles.body}>Profiles are ready. Posts arrive in milestone M2.</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  page: { flex: 1, backgroundColor: palette.background },
  empty: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: spacing.xl },
  title: { ...typeScale.title, color: palette.text },
  body: { ...typeScale.body, color: palette.textMuted, marginTop: spacing.sm, textAlign: 'center' },
});

