import { useMemo } from 'react';
import { Linking, ScrollView, StyleSheet, Text } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useQuery } from '@expo/snapback-react/familiar';

import { api } from '../../snapback/generated/api.mjs';
import { ProfileForm, palette, spacing, typeScale } from '../../ui';

export default function ProfileScreen() {
  const params = useLocalSearchParams<{ handle?: string }>();
  const router = useRouter();
  const handle = typeof params.handle === 'string' ? params.handle : '';
  const args = useMemo(() => ({ handle }), [handle]);
  const rows = useQuery(api.profiles.byHandle, args);
  const mineArgs = useMemo(() => ({}), []);
  const mineRows = useQuery(api.profiles.mine, mineArgs);
  const profile = rows?.[0];
  const mine = mineRows?.[0];

  if (!profile) {
    return <Text style={styles.status}>{rows === undefined ? 'Loading profile…' : 'Profile not found.'}</Text>;
  }
  const own = mine?._id === profile._id;
  const common = {
    avatarUri: profile.avatarUri ?? undefined,
    bio: profile.bio,
    displayName: profile.displayName,
    followerCount: 0,
    followingCount: 0,
    handle: profile.handle,
    link: profile.link,
    location: profile.location,
    onPressLink: (url: string) => void Linking.openURL(url),
  };
  return (
    <ScrollView contentContainerStyle={styles.page}>
      {own ? (
        <ProfileForm {...common} mode="view-own" onPressEdit={() => router.push('/profile/edit')} />
      ) : (
        <ProfileForm {...common} following={false} mode="view-other" onPressFollow={() => undefined} />
      )}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  page: { paddingVertical: spacing.lg, backgroundColor: palette.background },
  status: { ...typeScale.body, color: palette.textMuted, padding: spacing.xl },
});
}

async function composeTextPost(page, text, timeoutMs) {
  await openGlobalFeed(page, timeoutMs);
  await testId(page, "sm-compose-input").fill(text);
  await testId(page, "sm-compose-submit").click();
  const card = testId(page, "sm-feed-item").filter({ hasText: text }).first();
  await waitForLocator(card, { state: "visible", timeout: timeoutMs });
  return card;
}

async function openConversation(page, counterpart, timeoutMs) {
  const chat = testId(page, "sm-chats-item")
    .filter({ hasText: new RegExp(counterpart, "i") })
    .first();
  await waitForLocator(chat, { state: "visible", timeout: timeoutMs });
  await chat.click();
  await waitForLocator(testId(page, "sm-convo-input"), { state: "visible", timeout: timeoutMs });
}

async function openConversationFromAnySurface(ctx, page, counterpart) {
  if (await testId(page, "sm-convo-input").isVisible()) return;
  if (!(await testId(page, "sm-chats-item").first().isVisible())) {
    await page.goto(ctx.baseUrl, {
      waitUntil: "domcontentloaded",
      timeout: ctx.timeoutMs,
    });
  }
  await openConversation(page, counterpart, ctx.timeoutMs);
}

