          "import { mutation, query, v } from './generated/server';

export const follows = query({
  args: {},
  returns: v.array(v.doc('follows')),
  auth: 'authenticated',
  reads: ['follows'],
  handler: async (ctx) => ctx.db.query('follows').take(2000).collect(),
});

export const setFollow = mutation({
  args: { followedId: v.string(), set: v.boolean() },
  returns: v.object({ active: v.boolean() }),
  auth: 'authenticated',
  reads: ['profiles', 'follows'],
  writes: ['follows'],
  handler: async (ctx, args) => {
    const target = await ctx.db
      .query('profiles')
      .withIndex('by_user', (q) => q.eq('userId', args.followedId))
      .take(1)
      .collect();
    if (!target[0]) throw new Error('Profile does not exist.');
    if (args.followedId === ctx.auth.userId) return { active: false };
    const matches = await ctx.db
      .query('follows')
      .withIndex('by_pair', (q) => q.eq('followerId', ctx.auth.userId).eq('followedId', args.followedId))
      .take(1)
      .collect();
    const existing = matches[0];
    if (args.set && !existing) {
      await ctx.db.insert('follows', { followerId: ctx.auth.userId, followedId: args.followedId });
    }
    if (!args.set && existing) await ctx.db.delete('follows', existing._id);
    return { active: args.set };
  },
});
