        onPressLink={(url) => void Linking.openURL(url)}
        onPressReply={() => router.push(`/post/${post._id}`)}
        onPressRepost={() => void setRepost({ postId: post._id, set: !reposted, createdAt: Date.now() })}
        replyCount={replyCount}
        repostCount={repostCount}
        reposted={reposted}
        repostedByName={reposter?.displayName}
        text={post.text}
        timestamp={ageLabel(post.createdAt)}
        videoUri={post.videoUri ?? undefined}
      />
    );
  };

  const submit = (value: string) => {
    if (!mine || sending) return;
    setSending(true);
    setError('');
    void createPost({
      sourceId: sourceId(threadId ? 'reply' : 'post'),
      text: value.trim(),
      imageUris: [],
      createdAt: Date.now(),
      ...(threadId ? { parentPostId: threadId as never } : {}),
    })
      .then(() => setText(''))
      .catch((caught: unknown) => setError(caught instanceof Error ? caught.message : 'Could not publish.'))
      .finally(() => setSending(false));
  };

  if (threadId) {
    return (
      <View style={styles.page}>
        <ScrollView contentContainerStyle={styles.list}>
          <Text style={styles.heading}>Thread</Text>
          {parent ? renderPost(parent, `thread-parent-${parent._id}`) : <Text style={styles.status}>Loading thread…</Text>}
          {replies.map((reply) => renderPost(reply, `thread-reply-${reply._id}`))}
        </ScrollView>
        {error ? <Text style={styles.error}>{error}</Text> : null}
        <Composer maxLength={500} onChangeText={setText} onSend={submit} sending={sending} value={text} variant="post" />
      </View>
    );
  }

  const visible = feedEntries.slice(0, pageCount * PAGE_SIZE);
  return (
    <View style={styles.page}>
      <FeedTabs active={tab} onChange={setTab} />
      {tab === 'global' ? (
        <>
          {error ? <Text style={styles.error}>{error}</Text> : null}
          <Composer maxLength={500} onChangeText={setText} onSend={submit} sending={sending} value={text} variant="post" />
        </>
      ) : null}
      <ScrollView contentContainerStyle={styles.list}>
        {visible.map((entry) => renderPost(entry.post, entry.key, entry.reposterId))}
        {visible.length === 0 ? <Text style={styles.status}>No posts in this feed yet.</Text> : null}
