+  const actions = parseM2Log(await readFile(resolve(root, 'fixtures/starter-m2.log'), 'utf8'));
+  const receiptPath = resolve(root, 'receipts/m2-seed.jsonl');
+  await writeFile(receiptPath, '', 'utf8');
+  const profiles = await rows(m1.clientsByActor.get('alice'), api.profiles.all);
+  const profileByHandle = new Map(profiles.map((profile) => [profile.handle, profile]));
+
+  for (const action of actions) {
+    const client = m1.clientsByActor.get(action.actor);
+    assert(client, `M2 action requires M1 persona ${action.actor}`);
+    if (action.verb === 'follow') {
+      const target = profileByHandle.get(action.target);
+      assert(target, `follow target ${action.target} must exist`);
+      await mutate(client, api.social.setFollow, { followedId: target.userId, set: true }, `seed-m2-${action.sourceId}`);
+    } else if (action.verb === 'post') {
+      await mutate(client, api.posts.create, {
+        sourceId: action.sourceId,
+        text: action.text,
+        imageUris: action.imageUris,
+        createdAt: action.createdAt,
+        ...(action.videoUri ? { videoUri: action.videoUri } : {}),
+      }, `seed-m2-${action.sourceId}`);
+    } else if (action.verb === 'reply') {
+      const allPosts = await rows(client, api.posts.all);
+      const parent = allPosts.find((post) => post.sourceId === action.parentSourceId);
+      assert(parent, `reply parent ${action.parentSourceId} must exist`);
+      await mutate(client, api.posts.create, {
+        sourceId: action.sourceId,
+        text: action.text,
+        imageUris: [],
+        parentPostId: parent._id,
+        createdAt: action.createdAt,
+      }, `seed-m2-${action.sourceId}`);
+    } else {
+      const allPosts = await rows(client, api.posts.all);
+      const post = allPosts.find((candidate) => candidate.sourceId === action.postSourceId);
+      assert(post, `${action.verb} post ${action.postSourceId} must exist`);
+      if (action.verb === 'like') {
+        await mutate(client, api.posts.setLike, { postId: post._id, set: true }, `seed-m2-${action.sourceId}`);
+      } else {
+        await mutate(client, api.posts.setRepost, { postId: post._id, set: true, createdAt: action.createdAt }, `seed-m2-${action.sourceId}`);
+      }
+    }
+    await appendFile(receiptPath, `${JSON.stringify({ line: action.index, actor: action.actor, verb: action.verb, sourceId: action.sourceId, settled: true })}\n`);
+  }
+  return { actions: m1.actions + actions.length, m2Actions: actions.length, ...m1, receipt: 'receipts/m2-seed.jsonl' };
+}
+
+function followingProjection({ viewerId, posts, follows, reposts }) {
+  const followed = new Set(follows.filter((edge) => edge.followerId === viewerId).map((edge) => edge.followedId));
+  const originals = posts.filter((post) => !post.parentPostId && (post.authorId === viewerId || followed.has(post.authorId)));
+  const attributed = reposts
+    .filter((repost) => repost.userId === viewerId || followed.has(repost.userId))
+    .map((repost) => posts.find((post) => post._id === repost.postId))
+    .filter(Boolean);
+  return { originals, attributed };
+}
+
+async function runM2(writer) {
+  const startedAt = new Date().toISOString();
+  const replay = await replayM2();
+  const alice = replay.clientsByActor.get('alice');
+  const bob = replay.clientsByActor.get('bob');
+  assert(alice && bob);
+  const profiles = await rows(alice, api.profiles.all);
+  const aliceProfile = profiles.find((profile) => profile.handle === 'alice');
+  const bobProfile = profiles.find((profile) => profile.handle === 'bob');
+  const carolProfile = profiles.find((profile) => profile.handle === 'carol');
+  assert(aliceProfile && bobProfile && carolProfile);
+  const tests = [];
+  const coveredAssertions = [
+    'm2-a01', 'm2-a02', 'm2-a03', 'm2-a06', 'm2-a08', 'm2-a09', 'm2-a10', 'm2-a11',
+    'm2-a12', 'm2-a13', 'm2-a15', 'm2-a16', 'm2-a17', 'm2-a18', 'm2-a20', 'm2-a21',
+    'm2-a22', 'm2-a23', 'm2-a24', 'm2-a25', 'm2-a26', 'm2-a27',
+  ];
+
+  async function test(assertion, name, body) {
+    const began = performance.now();
+    try {
+      await body();
+      const durationMs = Math.max(0, performance.now() - began);
+      await writer.assertionWait('M2', { owner: 'suite', assertion, attempt: 1, durationMs, pass: true });
+      tests.push({ assertion, name, pass: true, durationMs });
+    } catch (error) {
+      const durationMs = Math.max(0, performance.now() - began);
+      await writer.assertionWait('M2', { owner: 'suite', assertion, attempt: 1, durationMs, pass: false });
+      tests.push({ assertion, name, pass: false, durationMs, error: error instanceof Error ? error.message : String(error) });
+      throw error;
+    }
+  }
+
+  await writer.claim('M2', 'browserAssertionWait', { owner: 'suite' });
+  const suffix = `${process.pid}-${Date.now()}`;
+  const created = {};
+  await test('m2-a01', 'create text post', async () => {
+    created.text = await mutate(alice, api.posts.create, { sourceId: `suite-text-${suffix}`, text: 'Suite post https://example.com/live', imageUris: [], createdAt: Date.now() }, `m2-text-${suffix}`);
+  });
+  await test('m2-a02', 'create post with two fixture images', async () => {
+    created.images = await mutate(alice, api.posts.create, { sourceId: `suite-images-${suffix}`, text: 'Two fixture images', imageUris: ['media/img-02.png', 'media/img-03.png'], createdAt: Date.now() + 1 }, `m2-images-${suffix}`);
+    const post = (await rows(alice, api.posts.all)).find((candidate) => candidate._id === created.images.postId);
+    assert.equal(post.imageUris.length, 2);
+  });
+  await test('m2-a03', 'create fixture video post', async () => {
+    created.video = await mutate(alice, api.posts.create, { sourceId: `suite-video-${suffix}`, text: 'Fixture video', imageUris: [], videoUri: 'media/vid-01.mp4', createdAt: Date.now() + 2 }, `m2-video-${suffix}`);
+    const post = (await rows(alice, api.posts.all)).find((candidate) => candidate._id === created.video.postId);
+    assert.equal(post.videoUri, 'media/vid-01.mp4');
+  });
+  await test('m2-a06', 'following projects Alice posts into Bob Following', async () => {
+    await mutate(bob, api.social.setFollow, { followedId: aliceProfile.userId, set: true }, `m2-follow-${suffix}`);
+    const projection = followingProjection({ viewerId: bobProfile.userId, posts: await rows(bob, api.posts.all), follows: await rows(bob, api.social.follows), reposts: await rows(bob, api.posts.reposts) });
