+    assert(!projection.originals.some((post) => post.authorId === carolProfile.userId));
+  });
+  await test('m2-a12', 'http URL is wired to tappable system-browser text', async () => {
+    const linkSource = await readFile(resolve(root, 'ui/src/linkify.tsx'), 'utf8');
+    const feedSource = await readFile(resolve(root, 'components/FeedSurface.tsx'), 'utf8');
+    assert(linkSource.includes('onPressLink'));
+    assert(feedSource.includes('Linking.openURL'));
+  });
+  await test('m2-a13', 'feed does not render URL preview cards', async () => {
+    const kit = await readFile(resolve(root, 'ui/src/FeedCard.tsx'), 'utf8');
+    assert(!kit.includes('previewCard'));
+    assert(!kit.includes('unfurl'));
+  });
+  await test('m2-a15', 'unlike clears set-state and decrements count', async () => {
+    await mutate(bob, api.posts.setLike, { postId: created.text.postId, set: true }, `m2-like-${suffix}`);
+    await mutate(bob, api.posts.setLike, { postId: created.text.postId, set: false }, `m2-unlike-${suffix}`);
+    const matches = (await rows(bob, api.posts.likes)).filter((like) => like.userId === bobProfile.userId && like.postId === created.text.postId);
+    assert.equal(matches.length, 0);
+  });
+  await test('m2-a16', 'repost stores attributable reposter identity', async () => {
+    await mutate(bob, api.posts.setRepost, { postId: created.text.postId, set: true, createdAt: Date.now() }, `m2-repost-${suffix}`);
+    const matches = (await rows(alice, api.posts.reposts)).filter((repost) => repost.userId === bobProfile.userId && repost.postId === created.text.postId);
+    assert.equal(matches.length, 1);
+    const kit = await readFile(resolve(root, 'ui/src/FeedCard.tsx'), 'utf8');
+    assert(kit.includes('Reposted by {repostedByName}'));
+  });
