+    assert.equal((await rows(bob, api.posts.reposts)).filter((repost) => repost.userId === bobProfile.userId && repost.postId === created.text.postId).length, 0);
+  });
+  await test('m2-a18', 'followed user repost surfaces original in Following', async () => {
