    }, 'membership role downgrade revokes B and deletes B typing');

    const publishError = await captureRejection(memberBOverlay.publish(
      { userHandle: recipientAPrincipal, name: 'Downgraded member B' },
      { ttlMs: typingRef.maxTtlMs },
