import { mutation, query, v } from './generated/server';

export const forConversation = query({
  args: { conversationId: v.id('conversations') },
  returns: v.array(v.doc('messages')),
  auth: 'authenticated',
  reads: ['conversationMemberships', 'messages'],
  handler: async (ctx, args) => {
    const membership = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    if (!membership[0]) throw new Error('Conversation membership is required.');
    return ctx.db
      .query('messages')
      .withIndex('by_conversation', (q) => q.eq('conversationId', args.conversationId))
      .order('createdAt', 'asc')
      .take(1024)
      .collect();
  },
});

export const send = mutation({
  args: {
    conversationId: v.id('conversations'),
    sourceId: v.string(),
    text: v.string(),
    quoteMessageId: v.optional(v.id('messages')),
    createdAt: v.number(),
  },
  returns: v.object({ messageId: v.id('messages') }),
  auth: 'authenticated',
  reads: ['conversationMemberships', 'messages'],
  writes: ['messages'],
  handler: async (ctx, args) => {
    if (args.text.trim().length < 1 || args.text.length > 2000) throw new Error('Messages must be 1–2000 characters.');
    const membership = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    if (!membership[0]) throw new Error('Conversation membership is required.');
    if (args.quoteMessageId) {
      const quoted = await ctx.db.get('messages', args.quoteMessageId);
      if (!quoted || quoted.conversationId !== args.conversationId) throw new Error('Quoted message must belong to this conversation.');
    }
    const prior = await ctx.db
      .query('messages')
      .withIndex('by_source', (q) => q.eq('sourceId', args.sourceId))
      .take(1)
      .collect();
    if (prior[0]) {
      if (prior[0].senderId !== ctx.auth.userId) throw new Error('Message source ID is already owned.');
      return { messageId: prior[0]._id };
    }
    const messageId = await ctx.db.insert('messages', {
      conversationId: args.conversationId,
      senderId: ctx.auth.userId,
      sourceId: args.sourceId,
      text: args.text,
      createdAt: args.createdAt,
      ...(args.quoteMessageId ? { quoteMessageId: args.quoteMessageId } : {}),
    });
    return { messageId };
  },
});

import { mutation, query, v } from './generated/server';

export const mine = query({
  args: {},
  returns: v.array(v.doc('conversations')),
  auth: 'authenticated',
  reads: ['conversations', 'conversationMemberships'],
  handler: async (ctx) => {
    const memberships = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_user', (q) => q.eq('userId', ctx.auth.userId))
      .take(1024)
      .collect();
    const conversations = await ctx.db.query('conversations').take(1024).collect();
    return conversations.filter((conversation) => memberships.some((membership) => membership.conversationId === conversation._id));
  },
});

export const memberships = query({
  args: { conversationId: v.id('conversations') },
  returns: v.array(v.doc('conversationMemberships')),
  auth: 'authenticated',
  reads: ['conversationMemberships'],
  handler: async (ctx, args) => {
    const mine = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    if (!mine[0]) throw new Error('Conversation membership is required.');
    return ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation', (q) => q.eq('conversationId', args.conversationId))
      .take(100)
      .collect();
  },
});

export const createDm = mutation({
  args: { otherUserId: v.string(), sourceId: v.string(), createdAt: v.number() },
  returns: v.object({ conversationId: v.id('conversations') }),
  auth: 'authenticated',
  reads: ['profiles', 'conversations', 'conversationMemberships'],
  writes: ['conversations', 'conversationMemberships'],
  handler: async (ctx, args) => {
    if (args.otherUserId === ctx.auth.userId) throw new Error('A DM requires another member.');
    const other = await ctx.db
      .query('profiles')
      .withIndex('by_user', (q) => q.eq('userId', args.otherUserId))
      .take(1)
      .collect();
    if (!other[0]) throw new Error('DM member does not exist.');
    const dmKey = ctx.auth.userId < args.otherUserId
      ? `${ctx.auth.userId}:${args.otherUserId}`
      : `${args.otherUserId}:${ctx.auth.userId}`;
    const existing = await ctx.db
      .query('conversations')
      .withIndex('by_dm_key', (q) => q.eq('dmKey', dmKey))
      .take(1)
      .collect();
    if (existing[0]) return { conversationId: existing[0]._id };
    const conversationId = await ctx.db.insert('conversations', {
      sourceId: args.sourceId,
      kind: 'dm',
      title: '',
      createdBy: ctx.auth.userId,
      dmKey,
      createdAt: args.createdAt,
    });
    await ctx.db.insert('conversationMemberships', { conversationId, userId: ctx.auth.userId, role: 'owner', joinedAt: args.createdAt });
    await ctx.db.insert('conversationMemberships', { conversationId, userId: args.otherUserId, role: 'member', joinedAt: args.createdAt });
    return { conversationId };
  },
});

export const createGroup = mutation({
  args: { sourceId: v.string(), title: v.string(), memberIds: v.array(v.string()), createdAt: v.number() },
  returns: v.object({ conversationId: v.id('conversations') }),
  auth: 'authenticated',
  reads: ['conversations', 'conversationMemberships'],
  writes: ['conversations', 'conversationMemberships'],
  handler: async (ctx, args) => {
    if (args.title.trim().length < 1 || args.title.length > 80) throw new Error('Group title must be 1–80 characters.');
    const prior = await ctx.db
      .query('conversations')
      .withIndex('by_source', (q) => q.eq('sourceId', args.sourceId))
      .take(1)
      .collect();
    if (prior[0]) {
      if (prior[0].createdBy !== ctx.auth.userId) throw new Error('Conversation source ID is already owned.');
      return { conversationId: prior[0]._id };
    }
    const conversationId = await ctx.db.insert('conversations', {
      sourceId: args.sourceId,
      kind: 'group',
      title: args.title,
      createdBy: ctx.auth.userId,
      dmKey: `group:${args.sourceId}`,
      createdAt: args.createdAt,
    });
    await ctx.db.insert('conversationMemberships', { conversationId, userId: ctx.auth.userId, role: 'owner', joinedAt: args.createdAt });
    for (const userId of args.memberIds) {
      if (userId !== ctx.auth.userId) {
        const existing = await ctx.db
          .query('conversationMemberships')
          .withIndex('by_conversation_user', (q) => q.eq('conversationId', conversationId).eq('userId', userId))
          .take(1)
          .collect();
        if (!existing[0]) await ctx.db.insert('conversationMemberships', { conversationId, userId, role: 'member', joinedAt: args.createdAt });
      }
    }
    return { conversationId };
  },
});

export const addMember = mutation({
  args: { conversationId: v.id('conversations'), userId: v.string(), joinedAt: v.number() },
  returns: v.object({ active: v.boolean() }),
  auth: 'authenticated',
  reads: ['conversationMemberships'],
  writes: ['conversationMemberships'],
  handler: async (ctx, args) => {
    const mine = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    if (!mine[0] || mine[0].role !== 'owner') throw new Error('Only the group owner can add members.');
    const existing = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', args.userId))
      .take(1)
      .collect();
    if (!existing[0]) await ctx.db.insert('conversationMemberships', { conversationId: args.conversationId, userId: args.userId, role: 'member', joinedAt: args.joinedAt });
    return { active: true };
  },
});

export const removeMember = mutation({
  args: { conversationId: v.id('conversations'), userId: v.string() },
  returns: v.object({ active: v.boolean() }),
  auth: 'authenticated',
  reads: ['conversationMemberships'],
  writes: ['conversationMemberships'],
  handler: async (ctx, args) => {
    const mine = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', ctx.auth.userId))
      .take(1)
      .collect();
    if (!mine[0] || mine[0].role !== 'owner') throw new Error('Only the group owner can remove members.');
    const target = await ctx.db
      .query('conversationMemberships')
      .withIndex('by_conversation_user', (q) => q.eq('conversationId', args.conversationId).eq('userId', args.userId))
      .take(1)
      .collect();
    if (target[0]?.role === 'owner') throw new Error('The owner cannot be removed.');
    if (target[0]) await ctx.db.delete('conversationMemberships', target[0]._id);
    return { active: false };
  },
});

