import { Composer, MessageBubble, TypingIndicator, palette, spacing, typeScale } from '../../ui';

function sourceId() {
  return `message-${globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`}`;
}

export default function ConversationScreen() {
  const params = useLocalSearchParams<{ id?: string }>();
  const conversationId = typeof params.id === 'string' ? params.id : '';
  const args = useMemo(() => ({ conversationId: conversationId as never }), [conversationId]);
  const emptyArgs = useMemo(() => ({}), []);
  const messages = useQuery(api.messages.forConversation, args) ?? [];
  const memberships = useQuery(api.conversations.memberships, args) ?? [];
  const profiles = useQuery(api.profiles.all, emptyArgs) ?? [];
  const mine = (useQuery(api.profiles.mine, emptyArgs) ?? [])[0];
  const sendMessage = useMutation(api.messages.send);
  const [body, setBody] = useState('');
  const [quoteId, setQuoteId] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState('');
  const profileByUser = useMemo(() => new Map(profiles.map((profile) => [profile.userId, profile])), [profiles]);
  const quote = quoteId ? messages.find((message) => message._id === quoteId) : undefined;
  const typing = useSnapbackActivityPresence(ephemeral.typing, {
    scope: { conversationId },
    value: () => ({ userId: mine?.userId ?? '', name: mine?.displayName ?? 'Member' }),
    idleMs: 3_000,
    ttlMs: 4_000,
  });
  const typers = typing.peers
    .map((entry) => entry.value)
    .filter((entry) => entry.userId !== mine?.userId && memberships.some((membership) => membership.userId === entry.userId));

  const changeBody = (text: string) => {
    setBody(text);
    if (text.trim()) typing.touch();
    else void typing.withdraw();
  };

  const submit = (text: string) => {
    if (!mine || sending || !text.trim()) return;
    setSending(true);
    setError('');
    void typing.withdraw();
    void sendMessage({
      conversationId: conversationId as never,
      sourceId: sourceId(),
      text: text.trim(),
      createdAt: Date.now(),
      ...(quote ? { quoteMessageId: quote._id } : {}),
    })
      .then(() => {
        setBody('');
        setQuoteId(null);
      })
      .catch((caught: unknown) => setError(caught instanceof Error ? caught.message : 'Could not send message.'))
      .finally(() => setSending(false));
  };

  return (
    <View style={styles.page}>
      <ScrollView contentContainerStyle={styles.messages}>
        <Text style={styles.heading}>Conversation</Text>
        {messages.map((message) => {
          const sender = profileByUser.get(message.senderId);
          const quoted = message.quoteMessageId ? messages.find((candidate) => candidate._id === message.quoteMessageId) : undefined;
          const quotedSender = quoted ? profileByUser.get(quoted.senderId) : undefined;
          return (
            <View key={message._id} style={styles.messageWrap} testID="sm-convo-bubble">
              <MessageBubble
                isMine={message.senderId === mine?.userId}
                onPressLink={(url) => void Linking.openURL(url)}
                onPressQuote={() => undefined}
                quote={quoted ? { senderName: quotedSender?.displayName ?? 'Member', excerpt: quoted.text.slice(0, 120) } : undefined}
                receipt={message.senderId === mine?.userId ? 'sent' : undefined}
                senderAvatarUri={sender?.avatarUri ?? undefined}
                senderName={sender?.displayName ?? 'Member'}
                showSender={message.senderId !== mine?.userId}
                testID="sm-convo-bubble-content"
                text={message.text}
              />
              <Pressable accessibilityLabel="Quote message" onPress={() => setQuoteId(message._id)} style={styles.quoteAction} testID="sm-convo-quote">
                <Text style={styles.quoteActionText}>Reply</Text>
              </Pressable>
            </View>
          );
        })}
        <TypingIndicator names={typers.map((entry) => entry.name)} visible={typers.length > 0} />
      </ScrollView>
      {quote ? <Text style={styles.quoting}>Replying to {profileByUser.get(quote.senderId)?.displayName ?? 'Member'}: {quote.text.slice(0, 80)}</Text> : null}
      {error ? <Text style={styles.error}>{error}</Text> : null}
      <Composer maxLength={2000} onChangeText={changeBody} onSend={submit} sending={sending} value={body} variant="message" />
    </View>
  );
}

const styles = StyleSheet.create({
  page: { flex: 1, backgroundColor: palette.background },
  messages: { paddingVertical: spacing.md },
  heading: { ...typeScale.title, color: palette.text, paddingHorizontal: spacing.lg, paddingBottom: spacing.md },
  messageWrap: { marginBottom: spacing.xs },
  quoteAction: { alignSelf: 'flex-end', paddingHorizontal: spacing.lg, paddingVertical: 2 },
  quoteActionText: { ...typeScale.caption, color: palette.primary },
  quoting: { ...typeScale.footnote, color: palette.textMuted, paddingHorizontal: spacing.lg, paddingVertical: spacing.xs },
  error: { ...typeScale.footnote, color: palette.danger, paddingHorizontal: spacing.lg },
});

