export const all = query({
  args: {},
  returns: v.array(v.doc('posts')),
  auth: 'authenticated',
  reads: ['posts'],
  handler: async (ctx) => ctx.db.query('posts').take(2000).collect(),
});

export const likes = query({
  args: {},
  returns: v.array(v.doc('likes')),
  auth: 'authenticated',
  reads: ['likes'],
  handler: async (ctx) => ctx.db.query('likes').take(5000).collect(),
});

export const reposts = query({
  args: {},
  returns: v.array(v.doc('reposts')),
  auth: 'authenticated',
  reads: ['reposts'],
  handler: async (ctx) => ctx.db.query('reposts').take(5000).collect(),
});

export const create = mutation({
  args: {
    sourceId: v.string(),
    text: v.string(),
    imageUris: v.array(v.string()),
    videoUri: v.optional(v.string()),
    parentPostId: v.optional(v.id('posts')),
    createdAt: v.number(),
  },
  returns: v.object({ postId: v.id('posts') }),
  auth: 'authenticated',
  reads: ['posts'],
  writes: ['posts'],
  handler: async (ctx, args) => {
    if (args.text.length > 500) throw new Error('Posts must be at most 500 characters.');
    if (args.imageUris.length > 4) throw new Error('Posts accept at most four images.');
    if (args.imageUris.length > 0 && args.videoUri) throw new Error('A post cannot mix images and video.');
    if (args.text.trim().length === 0 && args.imageUris.length === 0 && !args.videoUri) {
      throw new Error('A post must contain text or media.');
    }
    if (args.parentPostId) {
      const parent = await ctx.db.get('posts', args.parentPostId);
      if (!parent || parent.parentPostId) throw new Error('Replies require a top-level parent post.');
    }
    const prior = await ctx.db
      .query('posts')
      .withIndex('by_source', (q) => q.eq('sourceId', args.sourceId))
      .take(1)
      .collect();
    if (prior[0]) {
      if (prior[0].authorId !== ctx.auth.userId) throw new Error('Post source ID is already owned.');
      return { postId: prior[0]._id };
    }
    const postId = await ctx.db.insert('posts', {
      authorId: ctx.auth.userId,
      sourceId: args.sourceId,
      text: args.text,
      imageUris: args.imageUris,
      createdAt: args.createdAt,
      ...(args.videoUri ? { videoUri: args.videoUri } : {}),
      ...(args.parentPostId ? { parentPostId: args.parentPostId } : {}),
    });
    return { postId };
  },
});

export const setLike = mutation({
  args: { postId: v.id('posts'), set: v.boolean() },
  returns: v.object({ active: v.boolean() }),
  auth: 'authenticated',
  reads: ['posts', 'likes'],
  writes: ['likes'],
  handler: async (ctx, args) => {
    const post = await ctx.db.get('posts', args.postId);
    if (!post) throw new Error('Post does not exist.');
    const matches = await ctx.db
      .query('likes')
      .withIndex('by_pair', (q) => q.eq('userId', ctx.auth.userId).eq('postId', args.postId))
      .take(1)
      .collect();
    const existing = matches[0];
    if (args.set && !existing) await ctx.db.insert('likes', { userId: ctx.auth.userId, postId: args.postId });
    if (!args.set && existing) await ctx.db.delete('likes', existing._id);
    return { active: args.set };
  },
});

export const setRepost = mutation({
  args: { postId: v.id('posts'), set: v.boolean(), createdAt: v.number() },
  returns: v.object({ active: v.boolean() }),
  auth: 'authenticated',
  reads: ['posts', 'reposts'],
  writes: ['reposts'],
  handler: async (ctx, args) => {
    const post = await ctx.db.get('posts', args.postId);
    if (!post || post.parentPostId) throw new Error('Only top-level posts may be reposted.');
    const matches = await ctx.db
      .query('reposts')
      .withIndex('by_pair', (q) => q.eq('userId', ctx.auth.userId).eq('postId', args.postId))
      .take(1)
      .collect();
    const existing = matches[0];
    if (args.set && !existing) {
      await ctx.db.insert('reposts', { userId: ctx.auth.userId, postId: args.postId, createdAt: args.createdAt });
    }
    if (!args.set && existing) await ctx.db.delete('reposts', existing._id);
    return { active: args.set };
  },
});
